#!/usr/bin/env node
/*
 * scripts/docs/md-to-pdf.js
 *
 * Render Khy-OS markdown docs into BOTH:
 *   1) a self-contained, print-ready HTML page (beautiful on-screen reading:
 *      floating table of contents, styled tables / code / callouts, CJK fonts);
 *   2) a PDF generated by headless Chrome printing that same HTML.
 *
 * Zero new dependencies: reuses markdown-it already vendored in the repo
 * (extensions/khy-trae-bridge/node_modules/markdown-it) and the system
 * google-chrome for --print-to-pdf. Chinese renders via Noto Sans/Serif CJK.
 *
 * Usage:
 *   node scripts/docs/md-to-pdf.js <file.md> [more.md ...] [options]
 *   node scripts/docs/md-to-pdf.js --combined "标题" out-basename <a.md> <b.md>
 *
 * Options:
 *   --out-dir <dir>   Output directory (default: alongside each source .md)
 *   --html-only       Emit HTML only, skip the PDF step
 *   --pdf-only        Emit PDF only (a temp HTML is still rendered internally)
 *   --combined T B    Merge all inputs into one HTML/PDF titled T, basename B
 *   --preset onboarding
 *                     Regenerate the 使用入门→开发精通 growth-path set
 *                     (OPS-MAN-043 + 044, each standalone, plus a combined book).
 *
 * Exit non-zero on any failure with the real cause (no masking).
 */

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const REPO_ROOT = path.resolve(__dirname, '..', '..');

// --- locate markdown-it (vendored; fall back to a repo-wide search) ----------
function loadMarkdownIt() {
  const known = path.join(
    REPO_ROOT,
    'extensions/khy-trae-bridge/node_modules/markdown-it'
  );
  const candidates = [known];
  for (const c of candidates) {
    try {
      return require(c);
    } catch (_) {
      /* try next */
    }
  }
  throw new Error(
    'markdown-it not found. Expected at ' +
      known +
      ' (vendored in extensions/khy-trae-bridge).'
  );
}

// --- locate a chrome binary for --print-to-pdf -------------------------------
function findChrome() {
  const env = process.env.KHY_DOCS_CHROME || process.env.CHROME_PATH;
  const names = [
    env,
    'google-chrome-stable',
    'google-chrome',
    'chromium',
    'chromium-browser',
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ].filter(Boolean);
  for (const n of names) {
    try {
      execFileSync(n, ['--version'], { stdio: 'ignore' });
      return n;
    } catch (_) {
      /* try next */
    }
  }
  return null;
}

// --- heading slug for TOC anchors --------------------------------------------
function slugify(text, used) {
  let base = String(text)
    .trim()
    .replace(/[`*_~]/g, '')
    .replace(/\s+/g, '-')
    .replace(/[^\w一-鿿·.-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
  if (!base) base = 'sec';
  let slug = base;
  let i = 2;
  while (used.has(slug)) slug = base + '-' + i++;
  used.add(slug);
  return slug;
}

function htmlEscape(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// --- inline SVG passthrough (```svg fenced blocks) ---------------------------
// Docs carry hand-authored concept diagrams as ```svg blocks — zero external
// image files, offline-self-contained, print-crisp, git-diffable. We keep
// markdown-it's html:false (prose stays safe) and only let a SANITIZED subset of
// SVG through this dedicated fence. Anything scriptable is stripped: no <script>,
// no on*="" handlers, no external references (href/xlink:href to http/data),
// no <foreignObject> (can smuggle HTML). Failure is safe: on any doubt we escape.
function sanitizeSvg(raw) {
  let svg = String(raw);
  // Drop anything before the first <svg and after the last </svg> (defensive).
  const open = svg.indexOf('<svg');
  const close = svg.lastIndexOf('</svg>');
  if (open === -1 || close === -1) return null;
  svg = svg.slice(open, close + '</svg>'.length);
  // Strip scriptable / HTML-smuggling constructs.
  svg = svg
    .replace(/<\s*script[\s\S]*?<\s*\/\s*script\s*>/gi, '')
    .replace(/<\s*foreignObject[\s\S]*?<\s*\/\s*foreignObject\s*>/gi, '')
    .replace(/\son[a-z]+\s*=\s*"[^"]*"/gi, '')
    .replace(/\son[a-z]+\s*=\s*'[^']*'/gi, '')
    // neutralize external / data refs in href / xlink:href (keep in-doc #anchors)
    .replace(
      /(xlink:href|href)\s*=\s*"(?!#)[^"]*"/gi,
      '$1="#"'
    )
    .replace(/(xlink:href|href)\s*=\s*'(?!#)[^']*'/gi, "$1='#'")
    .replace(/javascript:/gi, '');
  // Reject if a raw <script or on-handler still slipped through after stripping.
  if (/<\s*script/i.test(svg) || /\son[a-z]+\s*=/i.test(svg)) return null;
  return svg;
}

// Register a ```svg fence rule that emits sanitized inline SVG (figure wrapper).
function installSvgFence(md) {
  const defaultFence =
    md.renderer.rules.fence ||
    function (tokens, idx, options, env, self) {
      return self.renderToken(tokens, idx, options);
    };
  md.renderer.rules.fence = function (tokens, idx, options, env, self) {
    const token = tokens[idx];
    const info = (token.info || '').trim().toLowerCase();
    if (info === 'svg') {
      const clean = sanitizeSvg(token.content);
      if (clean) return `<figure class="svg-figure">${clean}</figure>\n`;
      // Fall back to showing the source as a code block if it can't be trusted.
    }
    return defaultFence(tokens, idx, options, env, self);
  };
}

// --- cross-document reference auto-linking ------------------------------------
// Turn plain-text [OPS-MAN-059] / [IMPL-RPT-032] / [DEPLOY-MAN-015] / … mentions
// into links to the sibling .html in the same directory, so HTML readers get
// "前后文链接". Only rewrites bare text OUTSIDE existing <a>…</a>, <code>, <pre>,
// and outside href/id attributes. If no sibling file exists, the text is left
// untouched (no dead links).
const REF_TYPES =
  'OPS-MAN|IMPL-RPT|DEPLOY-MAN|DESIGN-ARCH|DESIGN-OTHER|MGMT-STD|MGMT-OTHER|INIT-PRD|TEST-RPT';
const REF_RE = new RegExp('\\[(' + REF_TYPES + ')-(\\d{3})\\]', 'g');

// Build id → sibling .html basename map by scanning a directory once.
function buildSiblingMap(dir) {
  const map = new Map(); // "OPS-MAN-059" -> "[OPS-MAN-059] ....md" basename (no ext)
  let files = [];
  try {
    files = fs.readdirSync(dir);
  } catch (_) {
    return map;
  }
  for (const f of files) {
    if (!f.endsWith('.md')) continue;
    const m = f.match(new RegExp('^\\[((?:' + REF_TYPES + ')-\\d{3})\\]'));
    if (m) map.set(m[1], f.replace(/\.md$/, ''));
  }
  return map;
}

// Rewrite refs inside an already-rendered HTML fragment, skipping code/anchors.
function linkifyRefs(html, siblingMap, selfId) {
  if (!siblingMap || siblingMap.size === 0) return html;
  // Split on protected regions (<a…>…</a>, <code>…</code>, <pre>…</pre>) and
  // only rewrite the unprotected slices.
  const protectedRe = /(<a\b[\s\S]*?<\/a>|<code\b[\s\S]*?<\/code>|<pre\b[\s\S]*?<\/pre>)/gi;
  const parts = html.split(protectedRe);
  for (let i = 0; i < parts.length; i++) {
    // Odd indices are the captured protected regions — leave untouched.
    if (i % 2 === 1) continue;
    parts[i] = parts[i].replace(REF_RE, (full, type, num) => {
      const id = type + '-' + num;
      if (id === selfId) return full; // don't self-link
      const base = siblingMap.get(id);
      if (!base) return full; // no sibling → keep plain text (no dead link)
      const href = encodeURI(base + '.html');
      return `<a class="xref" href="${href}" title="${id}">${full}</a>`;
    });
  }
  return parts.join('');
}

// Render one markdown string -> { bodyHtml, toc:[{level,text,slug}] }
function renderMarkdown(md, mdText) {
  const env = {};
  const tokens = md.parse(mdText, env);
  const used = new Set();
  const toc = [];
  // Assign ids to h2/h3 headings and collect TOC entries.
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t.type === 'heading_open' && (t.tag === 'h2' || t.tag === 'h3')) {
      const inline = tokens[i + 1];
      const text = inline && inline.content ? inline.content : '';
      const slug = slugify(text, used);
      t.attrSet('id', slug);
      toc.push({ level: t.tag === 'h2' ? 2 : 3, text, slug });
    }
  }
  const bodyHtml = md.renderer.render(tokens, md.options, env);
  return { bodyHtml, toc };
}

// --- the page template (embedded CSS; print + screen) ------------------------
function pageTemplate({ title, sections, toc, footer }) {
  const tocHtml = toc.length
    ? `<nav class="toc" aria-label="目录">
         <div class="toc-title">目录</div>
         <ul>${toc
           .map(
             (e) =>
               `<li class="lvl${e.level}"><a href="#${e.slug}">${htmlEscape(
                 e.text
               )}</a></li>`
           )
           .join('')}</ul>
       </nav>`
    : '';

  return `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${htmlEscape(title)}</title>
<style>
:root{
  --ink:#1f2328; --muted:#6b7280; --line:#e5e7eb; --bg:#ffffff;
  --accent:#2563eb; --accent-soft:#eff4ff; --code-bg:#f6f8fa; --code-ink:#24292f;
  --quote-bar:#9ab8ff; --quote-bg:#f7faff; --th-bg:#f3f6fb; --zebra:#fbfcfe;
  --maxw:860px;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0; color:var(--ink); background:#eef1f5;
  font-family:"Noto Sans CJK SC","PingFang SC","Microsoft YaHei","Source Han Sans SC",
    "Hiragino Sans GB","Helvetica Neue",Arial,sans-serif;
  font-size:15.5px; line-height:1.75; -webkit-font-smoothing:antialiased;
}
a{color:var(--accent); text-decoration:none}
a:hover{text-decoration:underline}

.layout{display:flex; gap:28px; max-width:1200px; margin:0 auto; padding:28px 22px 80px}
.toc{
  position:sticky; top:24px; align-self:flex-start; flex:0 0 232px; width:232px;
  max-height:calc(100vh - 48px); overflow:auto; font-size:13px; line-height:1.5;
  background:#fff; border:1px solid var(--line); border-radius:12px; padding:16px 14px;
}
.toc-title{font-weight:700; color:var(--muted); letter-spacing:.04em; font-size:12px;
  text-transform:uppercase; margin-bottom:10px}
.toc ul{list-style:none; margin:0; padding:0}
.toc li{margin:2px 0}
.toc li a{color:#374151; display:block; padding:3px 8px; border-radius:6px}
.toc li a:hover{background:var(--accent-soft); text-decoration:none}
.toc li.lvl3{padding-left:14px; font-size:12.5px; color:#6b7280}

.page{
  flex:1 1 auto; min-width:0; max-width:var(--maxw); margin:0 auto;
  background:var(--bg); border:1px solid var(--line); border-radius:14px;
  padding:46px 52px 56px; box-shadow:0 1px 3px rgba(16,24,40,.06),0 8px 24px rgba(16,24,40,.05);
}

h1{font-size:27px; line-height:1.35; margin:.2em 0 .6em; font-weight:800;
  padding-bottom:.45em; border-bottom:2px solid var(--line)}
h2{font-size:21px; margin:1.7em 0 .7em; font-weight:750; padding-bottom:.3em;
  border-bottom:1px solid var(--line)}
h3{font-size:17px; margin:1.4em 0 .5em; font-weight:700; color:#111827}
h2::before{content:""; display:inline-block; width:4px; height:.92em; background:var(--accent);
  border-radius:2px; margin-right:.5em; vertical-align:-1px}
h1,h2,h3{scroll-margin-top:20px}

p{margin:.7em 0}
strong{font-weight:700}
hr{border:0; border-top:1px solid var(--line); margin:1.8em 0}

ul,ol{padding-left:1.4em; margin:.6em 0}
li{margin:.28em 0}
li>p{margin:.3em 0}

code{
  font-family:"SF Mono","JetBrains Mono",Menlo,Consolas,"Noto Sans Mono CJK SC",monospace;
  font-size:.88em; background:var(--code-bg); color:var(--code-ink);
  padding:.12em .42em; border-radius:5px; border:1px solid #eaecef}
pre{
  background:var(--code-bg); border:1px solid #e1e4e8; border-radius:10px;
  padding:14px 16px; overflow:auto; margin:1em 0; line-height:1.55}
pre code{background:none; border:0; padding:0; font-size:13px; color:#1f2328; white-space:pre}

blockquote{
  margin:1em 0; padding:.6em 1em .6em 1.1em; color:#3f4651;
  background:var(--quote-bg); border-left:4px solid var(--quote-bar); border-radius:0 8px 8px 0}
blockquote p{margin:.35em 0}

table{border-collapse:collapse; width:100%; margin:1.1em 0; font-size:14px; overflow:hidden;
  border:1px solid var(--line); border-radius:10px}
thead th{background:var(--th-bg); text-align:left}
th,td{border:1px solid var(--line); padding:8px 12px; vertical-align:top}
tbody tr:nth-child(even){background:var(--zebra)}
td code,th code{white-space:nowrap}

.doc-cover{margin-bottom:8px}
.doc-cover .brand{display:inline-block; font-size:12px; font-weight:700; letter-spacing:.12em;
  color:var(--accent); background:var(--accent-soft); padding:4px 10px; border-radius:999px;
  text-transform:uppercase}
.doc-meta{color:var(--muted); font-size:12.5px; margin:18px 0 0; padding-top:14px;
  border-top:1px dashed var(--line)}
.section + .section{margin-top:18px}
.section-break{break-before:page}

/* ----- inline SVG figures ----- */
.svg-figure{margin:1.4em 0; text-align:center}
.svg-figure svg{max-width:100%; height:auto; background:#fff;
  border:1px solid var(--line); border-radius:12px; padding:14px 16px;
  box-shadow:0 1px 2px rgba(16,24,40,.05)}
.svg-figure figcaption{color:var(--muted); font-size:12.5px; margin-top:8px}

/* ----- cross-doc reference links ----- */
a.xref{color:var(--accent); background:var(--accent-soft); border-radius:5px;
  padding:0 .28em; text-decoration:none; white-space:nowrap;
  border-bottom:1px dashed transparent}
a.xref:hover{border-bottom-color:var(--accent); text-decoration:none}

/* ----- heading hover permalinks ----- */
.headline{position:relative}
.headline .anchor{position:absolute; left:-1.05em; top:0; opacity:0;
  color:var(--muted); font-weight:400; text-decoration:none; padding:0 .15em;
  transition:opacity .12s}
.headline:hover .anchor{opacity:.7}
.headline .anchor:hover{opacity:1; color:var(--accent)}

/* ----- TOC active highlight ----- */
.toc li a.active{background:var(--accent-soft); color:var(--accent); font-weight:600}

/* ----- back-to-top button ----- */
#backTop{position:fixed; right:22px; bottom:24px; width:42px; height:42px;
  border-radius:50%; border:1px solid var(--line); background:#fff; color:var(--accent);
  font-size:18px; line-height:40px; text-align:center; cursor:pointer; opacity:0;
  pointer-events:none; transition:opacity .18s, transform .18s;
  box-shadow:0 4px 14px rgba(16,24,40,.14); z-index:50}
#backTop.show{opacity:1; pointer-events:auto}
#backTop:hover{transform:translateY(-2px)}

/* ----- print / PDF ----- */
@page{ size:A4; margin:16mm 15mm 18mm; }
@media print{
  body{background:#fff; font-size:12pt; line-height:1.6}
  .layout{display:block; max-width:none; margin:0; padding:0}
  .toc{display:none}
  .page{max-width:none; margin:0; border:0; border-radius:0; box-shadow:none; padding:0}
  h1{font-size:21pt} h2{font-size:16pt} h3{font-size:13pt}
  pre,blockquote,table,tr,img,.svg-figure{break-inside:avoid}
  h1,h2,h3{break-after:avoid}
  a,a.xref{color:var(--ink); background:none}
  .headline .anchor,#backTop{display:none}
  .svg-figure svg{box-shadow:none}
  pre{white-space:pre-wrap; word-break:break-word}
}
</style>
</head>
<body>
<div class="layout">
  ${tocHtml}
  <main class="page">
    ${sections}
    ${footer ? `<div class="doc-meta">${footer}</div>` : ''}
  </main>
</div>
<button id="backTop" aria-label="回到顶部" title="回到顶部">↑</button>
<script>
(function(){
  "use strict";
  var docEl=document.documentElement;
  // 1) 标题锚点永久链接：给带 id 的 h2/h3 注入可悬停复制的 # 链接
  try{
    var heads=document.querySelectorAll("h1[id],h2[id],h3[id]");
    for(var i=0;i<heads.length;i++){
      var h=heads[i];
      if(h.querySelector(".anchor")) continue;
      h.classList.add("headline");
      var a=document.createElement("a");
      a.className="anchor"; a.href="#"+h.id;
      a.setAttribute("aria-label","本节链接"); a.textContent="#";
      h.insertBefore(a,h.firstChild);
    }
  }catch(e){}
  // 2) 目录高亮：滚动时把当前可见小节对应的 TOC 项标 .active
  try{
    var links={};
    var tocAnchors=document.querySelectorAll(".toc li a[href^='#']");
    for(var j=0;j<tocAnchors.length;j++){
      var id=decodeURIComponent(tocAnchors[j].getAttribute("href").slice(1));
      if(id) links[id]=tocAnchors[j];
    }
    var targets=[];
    for(var k in links){ if(Object.prototype.hasOwnProperty.call(links,k)){
      var el=document.getElementById(k); if(el) targets.push(el);
    }}
    if("IntersectionObserver" in window && targets.length){
      var active=null;
      var io=new IntersectionObserver(function(entries){
        for(var m=0;m<entries.length;m++){
          var en=entries[m];
          if(en.isIntersecting){
            var lk=links[en.target.id];
            if(lk && lk!==active){
              if(active) active.classList.remove("active");
              lk.classList.add("active"); active=lk;
              // 让高亮项在 TOC 视口内可见
              if(lk.scrollIntoView){ try{ lk.scrollIntoView({block:"nearest"}); }catch(_){} }
            }
          }
        }
      },{rootMargin:"0px 0px -70% 0px",threshold:0});
      for(var n=0;n<targets.length;n++) io.observe(targets[n]);
    }
  }catch(e){}
  // 3) 回到顶部：滚过 ~400px 显示，点击平滑回顶
  try{
    var bt=document.getElementById("backTop");
    if(bt){
      var onScroll=function(){
        var y=window.pageYOffset||docEl.scrollTop||0;
        if(y>400) bt.classList.add("show"); else bt.classList.remove("show");
      };
      window.addEventListener("scroll",onScroll,{passive:true});
      onScroll();
      bt.addEventListener("click",function(){
        try{ window.scrollTo({top:0,behavior:"smooth"}); }
        catch(_){ window.scrollTo(0,0); }
      });
    }
  }catch(e){}
})();
</script>
</body>
</html>`;
}

// --- chrome print-to-pdf -----------------------------------------------------
function printPdf(chrome, htmlPath, pdfPath) {
  const args = [
    '--headless=new',
    '--disable-gpu',
    '--no-sandbox',
    '--no-pdf-header-footer',
    '--run-all-compositor-stages-before-draw',
    '--virtual-time-budget=15000',
    '--print-to-pdf=' + pdfPath,
    'file://' + encodeURI(htmlPath),
  ];
  try {
    execFileSync(chrome, args, { stdio: 'ignore' });
  } catch (e) {
    // Older chrome rejects --headless=new; retry with classic flag.
    const legacy = args.slice();
    legacy[0] = '--headless';
    execFileSync(chrome, legacy, { stdio: 'ignore' });
  }
  if (!fs.existsSync(pdfPath)) {
    throw new Error('Chrome did not produce a PDF at ' + pdfPath);
  }
}

// --- argument parsing --------------------------------------------------------
function parseArgs(argv) {
  const opts = {
    inputs: [],
    outDir: null,
    htmlOnly: false,
    pdfOnly: false,
    combined: null, // { title, base }
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--out-dir') opts.outDir = argv[++i];
    else if (a === '--html-only') opts.htmlOnly = true;
    else if (a === '--pdf-only') opts.pdfOnly = true;
    else if (a === '--combined') {
      opts.combined = { title: argv[++i], base: argv[++i] };
    } else opts.inputs.push(a);
  }
  return opts;
}

function docTitleFromMd(mdText, fallback) {
  const m = mdText.match(/^#\s+(.+?)\s*$/m);
  return m ? m[1].replace(/[`*]/g, '') : fallback;
}

// The 使用入门→开发精通 growth-path docs (single source of truth for the preset).
const ONBOARDING_OPS_DIR = path.join(REPO_ROOT, 'docs/07_OPS_运维');
const ONBOARDING_DOCS = [
  '[OPS-MAN-043] 从0到高手-新手成长路线与pip安装后清单.md',
  '[OPS-MAN-044] 从使用入门到开发精通-开发者成长路线.md',
];

function runPreset(name) {
  if (name !== 'onboarding') {
    console.error('Unknown preset: ' + name + ' (known: onboarding)');
    process.exit(2);
  }
  const inputs = ONBOARDING_DOCS.map((f) => path.join(ONBOARDING_OPS_DIR, f));
  for (const f of inputs) {
    if (!fs.existsSync(f)) {
      console.error('Preset source missing: ' + f);
      process.exit(4);
    }
  }
  const node = process.execPath;
  const self = __filename;
  // 1) each doc standalone (HTML + PDF)
  execFileSync(node, [self, ...inputs], { stdio: 'inherit' });
  // 2) the combined book
  execFileSync(
    node,
    [
      self,
      '--combined',
      'khy 从使用入门到开发精通 · 完整成长路线',
      '[OPS-MAN-043+044] 从使用入门到开发精通-合订本',
      ...inputs,
    ],
    { stdio: 'inherit' }
  );
}

function main() {
  const presetIdx = process.argv.indexOf('--preset');
  if (presetIdx !== -1) {
    runPreset(process.argv[presetIdx + 1]);
    return;
  }
  const opts = parseArgs(process.argv.slice(2));
  if (!opts.inputs.length) {
    console.error(
      'usage: node scripts/docs/md-to-pdf.js <file.md> [...] ' +
        '[--out-dir D] [--html-only|--pdf-only] [--combined "标题" basename]'
    );
    process.exit(2);
  }
  const MarkdownIt = loadMarkdownIt();
  const md = new MarkdownIt({ html: false, linkify: true, typographer: false });
  installSvgFence(md);

  const chrome = opts.pdfOnly || !opts.htmlOnly ? findChrome() : null;
  if (!opts.htmlOnly && !chrome) {
    console.error(
      'No chrome binary found for PDF export. Install google-chrome, ' +
        'or set KHY_DOCS_CHROME, or pass --html-only.'
    );
    process.exit(3);
  }

  const written = [];

  function emit(htmlPath, pdfBase, html) {
    if (!opts.pdfOnly) {
      fs.writeFileSync(htmlPath, html, 'utf8');
      written.push(htmlPath);
    }
    if (!opts.htmlOnly) {
      // Need an on-disk HTML for chrome even in --pdf-only mode.
      let src = htmlPath;
      let tmp = null;
      if (opts.pdfOnly) {
        tmp = path.join(os.tmpdir(), 'khydoc-' + process.pid + '-' + path.basename(pdfBase) + '.html');
        fs.writeFileSync(tmp, html, 'utf8');
        src = tmp;
      }
      const pdfPath = pdfBase + '.pdf';
      printPdf(chrome, src, pdfPath);
      written.push(pdfPath);
      if (tmp) fs.unlinkSync(tmp);
    }
  }

  if (opts.combined) {
    const sections = [];
    let allToc = [];
    const usedGlobal = new Set();
    opts.inputs.forEach((inp, idx) => {
      const mdText = fs.readFileSync(inp, 'utf8');
      // Re-render with a per-file id namespace to avoid anchor collisions.
      const env = {};
      const tokens = md.parse(mdText, env);
      for (let i = 0; i < tokens.length; i++) {
        const t = tokens[i];
        if (t.type === 'heading_open' && (t.tag === 'h2' || t.tag === 'h3')) {
          const inline = tokens[i + 1];
          const text = inline && inline.content ? inline.content : '';
          const slug = slugify('p' + idx + '-' + text, usedGlobal);
          t.attrSet('id', slug);
          allToc.push({ level: t.tag === 'h2' ? 2 : 3, text, slug });
        }
      }
      const body = md.renderer.render(tokens, md.options, env);
      sections.push(
        `<section class="section${idx > 0 ? ' section-break' : ''}">${body}</section>`
      );
    });
    // Cross-doc reference auto-linking: siblings live beside the first input.
    const combSiblings = buildSiblingMap(path.dirname(opts.inputs[0]));
    const html = pageTemplate({
      title: opts.combined.title,
      sections: linkifyRefs(sections.join('\n'), combSiblings, null),
      toc: allToc,
      footer:
        'Khy-OS 文档 · 由 scripts/docs/md-to-pdf.js 生成 · 内容以仓库 markdown 为准',
    });
    const outDir = opts.outDir || path.dirname(opts.inputs[0]);
    const base = path.join(outDir, opts.combined.base);
    emit(base + '.html', base, html);
  } else {
    for (const inp of opts.inputs) {
      const mdText = fs.readFileSync(inp, 'utf8');
      const title = docTitleFromMd(mdText, path.basename(inp, '.md'));
      const { bodyHtml, toc } = renderMarkdown(md, mdText);
      // Auto-link [SECTION-TYPE-NNN] refs to sibling .html in the same dir.
      const siblings = buildSiblingMap(path.dirname(inp));
      const selfMatch = path
        .basename(inp)
        .match(new RegExp('^\\[((?:' + REF_TYPES + ')-\\d{3})\\]'));
      const selfId = selfMatch ? selfMatch[1] : null;
      const html = pageTemplate({
        title,
        sections: `<section class="section">${linkifyRefs(
          bodyHtml,
          siblings,
          selfId
        )}</section>`,
        toc,
        footer:
          'Khy-OS 文档 · 由 scripts/docs/md-to-pdf.js 生成 · 内容以仓库 markdown 为准',
      });
      const outDir = opts.outDir || path.dirname(inp);
      const base = path.join(outDir, path.basename(inp, '.md'));
      emit(base + '.html', base, html);
    }
  }

  console.log('Wrote:');
  for (const w of written) console.log('  ' + w);
}

main();
